mapper.select:
SELECT b.id, b.title, b.author, b.price, b.publish_date, b.description, b.category_id, c.name AS category_name, b.total_stock, b.available_stock, b.version FROM book b LEFT JOIN category c ON b.category_id = c.id WHERE b.category_id IN
#{id}
ORDER BY b.id DESC

mapper.update:
UPDATE book
SET available_stock = available_stock - 1,
    version = version + 1
WHERE id = #{id}
  AND version = #{version}
  AND available_stock > 0

UPDATE book
SET available_stock = available_stock + 1
WHERE id = #{id}
